import {SUPABASE_URL,SUPABASE_KEY} from './supabase-config.js';
import {escapeHTML,safeImage} from './catalog.js';
const $=s=>document.querySelector(s);
const message=text=>{$('#message').textContent=text;};
let db,products=[],currentImage='',previewURL='',busy=false,recovering=location.hash.includes('type=recovery');
const editor=$('#product-dialog'),form=$('#product-form');
function setBusy(value){busy=value;form.querySelectorAll('button').forEach(b=>b.disabled=value);$('#save-product').textContent=value?'Saving…':'Save product';}
async function authorized(){const {data:{user},error}=await db.auth.getUser();if(error||!user)return false;const result=await db.from('miroku_admins').select('user_id').eq('user_id',user.id).maybeSingle();if(result.error)throw new Error('Database setup is incomplete. Follow the Supabase setup guide in the repository.');return !!result.data;}
async function showWorkspace(){try{if(!await authorized()){await db.auth.signOut();message('This account does not have store admin access.');return;}$('#login-panel').hidden=true;$('#password-panel').hidden=true;$('#workspace').hidden=false;message('');await refresh();}catch(e){message(e.message);}}
async function refresh(){const {data,error}=await db.from('miroku_products').select('*').order('created_at',{ascending:false});if(error)throw new Error('Could not load products. Check the database setup and try Refresh.');products=data;render();}
function render(){const currency=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR'}).format(n);$('#product-count').textContent=`${products.length} product${products.length===1?'':'s'} · ${products.filter(p=>p.published).length} published`;$('#product-list').innerHTML=products.length?products.map(p=>`<article class="admin-product"><img src="${escapeHTML(safeImage(p.image))}" alt="${escapeHTML(p.name)}"><span class="status-label">${p.published?'Published':'Draft'}</span><h2>${escapeHTML(p.name)}</h2><p>${currency(p.price)} · ${p.stock} in stock</p><p>${escapeHTML(p.category)}</p><div class="actions"><button class="secondary" data-edit="${p.id}">Edit</button><button class="text-button" data-toggle="${p.id}">${p.published?'Unpublish':'Publish'}</button></div></article>`).join(''):'<div class="empty-admin"><h2>Your collection starts here.</h2><p>Add your first product, upload a photo, and publish when it is ready.</p></div>';}
function closeEditor(){if(busy)return;editor.close();if(previewURL)URL.revokeObjectURL(previewURL);previewURL='';}
function openEditor(p){form.reset();$('#editor-message').textContent='';currentImage=p?.image||'';if(previewURL)URL.revokeObjectURL(previewURL);previewURL='';for(const key of ['id','name','category','price','stock','color','tag','description'])form.elements[key].value=p?.[key]??(key==='stock'?0:'');form.elements.published.checked=!!p?.published;$('#editor-title').textContent=p?'Edit product':'Add product';$('#photo-preview').hidden=!currentImage;$('#photo-preview').src=safeImage(currentImage);editor.showModal();}
async function compressPhoto(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024)throw new Error('Choose a JPEG, PNG or WebP photo smaller than 10 MB.');const bitmap=await createImageBitmap(file);const scale=Math.min(1,1600/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/webp',.85));if(!blob||blob.size>5*1024*1024)throw new Error('Photo could not be resized. Try a smaller photo.');return blob;}
$('#login-form').addEventListener('submit',async e=>{e.preventDefault();const login=e.currentTarget;const b=login.querySelector('button');b.disabled=true;try{const {error}=await db.auth.signInWithPassword({email:login.email.value.trim(),password:login.password.value});if(error)throw new Error('Sign-in failed. Check your email and password.');login.password.value='';await showWorkspace();}catch(err){message(err.message);}finally{b.disabled=false;}});
$('#reset-password').addEventListener('click',async()=>{const email=$('#login-form').email.value.trim();if(!email){message('Enter your email first.');return;}const {error}=await db.auth.resetPasswordForEmail(email,{redirectTo:`${location.origin}/admin`});message(error?'Could not send the reset link. Please try again.':'If this account exists, a password reset link will be sent to your email.');});
$('#password-form').addEventListener('submit',async e=>{e.preventDefault();const passwordForm=e.currentTarget;const b=passwordForm.querySelector('button');b.disabled=true;const {error}=await db.auth.updateUser({password:passwordForm.password.value});b.disabled=false;if(error){message('Could not update your password. Request a new reset link.');return;}passwordForm.reset();recovering=false;await showWorkspace();});
$('#sign-out').addEventListener('click',async()=>{const {error}=await db.auth.signOut();if(error){message('Could not sign out. Please try again.');return;}products=[];$('#workspace').hidden=true;$('#product-list').replaceChildren();$('#login-panel').hidden=false;message('Signed out.');});
$('#refresh').addEventListener('click',()=>refresh().catch(e=>message(e.message)));$('#new-product').addEventListener('click',()=>openEditor());$('#close-editor').addEventListener('click',closeEditor);$('#cancel-editor').addEventListener('click',closeEditor);editor.addEventListener('cancel',e=>{if(busy)e.preventDefault();});
form.elements.photo.addEventListener('change',()=>{const file=form.elements.photo.files[0];if(previewURL)URL.revokeObjectURL(previewURL);previewURL='';if(file&&['image/jpeg','image/png','image/webp'].includes(file.type)&&file.size<=10*1024*1024){previewURL=URL.createObjectURL(file);$('#photo-preview').src=previewURL;$('#photo-preview').hidden=false;$('#editor-message').textContent='';}else{form.elements.photo.value='';$('#photo-preview').src=safeImage(currentImage);$('#photo-preview').hidden=!currentImage;$('#editor-message').textContent=file?'Choose a supported photo smaller than 10 MB.':'';}});
form.addEventListener('submit',async e=>{e.preventDefault();if(busy)return;setBusy(true);let uploadedPath;try{if(!await authorized())throw new Error('Your session expired. Sign in again.');const id=form.elements.id.value||crypto.randomUUID();const fields=new FormData(form);const price=Number(fields.get('price')),stock=Number(fields.get('stock'));if(!Number.isFinite(price)||price<=0||price>10000000||!Number.isInteger(stock)||stock<0||stock>1000000)throw new Error('Enter a valid price and whole-number stock quantity.');let image=currentImage;const photo=form.elements.photo.files[0];if(photo){const blob=await compressPhoto(photo);uploadedPath=`${id}/${crypto.randomUUID()}.webp`;const {error}=await db.storage.from('miroku-product-images').upload(uploadedPath,blob,{contentType:'image/webp',upsert:false});if(error)throw new Error('Photo upload failed. Check the storage setup and try again.');image=db.storage.from('miroku-product-images').getPublicUrl(uploadedPath).data.publicUrl;}if(!safeImage(image))throw new Error('Upload a product photo before saving.');const record={id,name:fields.get('name').trim(),category:fields.get('category').trim(),description:fields.get('description').trim(),color:fields.get('color').trim(),tag:fields.get('tag').trim(),price,stock,image,published:form.elements.published.checked};if(!record.name||!record.category||!record.description)throw new Error('Name, category and description cannot be blank.');const result=form.elements.id.value?await db.from('miroku_products').update(record).eq('id',id).select('id').single():await db.from('miroku_products').insert(record).select('id').single();if(result.error)throw new Error('Product was not saved. Check your connection and admin permissions.');uploadedPath=undefined;setBusy(false);closeEditor();message('Product saved. Published changes appear in the store on refresh.');await refresh();}catch(err){if(uploadedPath)await db.storage.from('miroku-product-images').remove([uploadedPath]);$('#editor-message').textContent=err.message;}finally{setBusy(false);}});
$('#product-list').addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const p=products.find(p=>p.id===(b.dataset.edit||b.dataset.toggle));if(!p)return;if(b.dataset.edit){openEditor(p);return;}b.disabled=true;try{const {data,error}=await db.from('miroku_products').update({published:!p.published}).eq('id',p.id).select('id').single();if(error||!data)throw new Error('Could not change publication status. Sign in again and retry.');await refresh();message(p.published?'Product unpublished.':'Product published.');}catch(err){message(err.message);}finally{b.disabled=false;}});
try{const {createClient}=await import('https://esm.sh/@supabase/supabase-js@2.57.4');db=createClient(SUPABASE_URL,SUPABASE_KEY);$('#login-form button').disabled=false;$('#reset-password').disabled=false;db.auth.onAuthStateChange((event)=>{if(event==='PASSWORD_RECOVERY'){recovering=true;$('#login-panel').hidden=true;$('#workspace').hidden=true;$('#password-panel').hidden=false;}if(event==='SIGNED_OUT'){products=[];$('#workspace').hidden=true;$('#password-panel').hidden=true;$('#login-panel').hidden=false;}});const {data:{session}}=await db.auth.getSession();if(recovering){$('#login-panel').hidden=true;$('#password-panel').hidden=false;}else if(session)await showWorkspace();}catch{message('Could not connect to the admin service. Please refresh and try again.');$('#login-form button').disabled=true;$('#reset-password').disabled=true;}
